// === Tab: mySketch ===
// work: Lissajous dots [interactive]
// author: k0ch
// date: 2019-09-02

// Math usage:
// - Lissajous curve
// - Linear interpolation

let points = [];

//example coef values
let sin_coef = 0.002;
let cos_coef = 0.002;
let diff_coef = 20;
let size_coef = 200;
let delta = 0.0001;


const points_num = 720;

function preload() {
  dot = loadImage("https://openprocessing.org/sketch/1451917/files/dots.png");
  halo = loadImage("https://openprocessing.org/sketch/1451917/files/dotg.png");	
}

function setup() {
	//initialize environment
	createCanvas(windowWidth, windowHeight, WEBGL);
	background(0);

	//initialize points
	for (let i = 0; i < points_num; i++) {
		points[i] = [0,0]
  }

	//initialize coefficients
	sin_coef = random(0.0001, 0.009);
  cos_coef = random(0.0001, 0.009);
	diff_coef = random(15, 30);
	size_coef = random(200, 300);
}

function draw() {
	//center of image
	cx = windowWidth/2;
	cy = windowHeight/2;

	//time
  t = millis()/1;

	//reset draw
	background(0);

	// draw halo
  for (let i = 0; i < points_num; i++)
  {
    points[i][0] = lerp(points[i][0], size_coef * sin((t+i*diff_coef)*sin_coef), 0.15);
    points[i][1] = lerp(points[i][1], size_coef * cos((t+i*diff_coef)*cos_coef), 0.15); 
    //image(halo, cx - 25 + points[i][0], cy - 25 + points[i][1]);
  }

	// draw points
  for (let i = 0; i < points_num; i++)
  {
    image(dot, cx + points[i][0], cy + points[i][1]);
  }
	//rotateY(frameCount);
}

function mousePressed() {
  sin_coef += delta; //
	if (sin_coef > 0.009) {sin_coef = random(0.0001, 0.009);}
  cos_coef += delta; //
	if (cos_coef > 0.009) {cos_coef = random(0.0001, 0.009);}
	diff_coef = random(15, 50);
	size_coef = random(200, 400);
}

